const express = require('express');
const app = express();

// Parse JSON body
app.use(express.json());

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Sample users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Reference rule engine evaluator
// Endpoints accept a `rule` expression evaluated against the request context.
// The engine MUST support arbitrary JS expressions for flexibility; use the reference evaluator below as-is.

function evalRule(req) {
  // The caller provides a JS expression in the rule field.
  // For example: 'ctx.amount > 100'
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  // Dynamically evaluate the expression in a sandboxed context.
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

// POST /check endpoint: evaluate the rule against the context supplied in the request body.
app.post('/check', (req, res) => {
  try {
    const evaluation = evalRule(req);
    res.json({ result: evaluation });
  } catch (e) {
    // If evaluation fails, return a 400 with the error message.
    res.status(400).json({ error: e.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

