  // Dynamic evaluation of the expression with `ctx` and `req` as globals
  // The expression is wrapped in parentheses to ensure it returns the value
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

// POST /check endpoint: evaluates supplied rule against request context
app.post('/check', (req, res) => {
  try {
    const result = evalRule(req);
    // Respond with a simple JSON payload indicating whether the rule matched
    res.json({ result });
  } catch (err) {
    // Return a 400 Bad Request for any evaluation errors
    res.status(400).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
